/* Website logo manager — CMS upload + public live branding */
(()=>{const SB='https://xleceiffuopioeguniwj.supabase.co',KEY='sb_publishable_POksYryhG_mkFbs7N0fjKQ_4dUim7Ex',admin=location.pathname.startsWith('/cms');const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const style=document.createElement('style');style.id='site-logo-manager-style';style.textContent=`
.site-brand-logo{display:block!important;max-width:170px!important;width:auto!important;height:44px!important;object-fit:contain!important;object-position:left center!important;border-radius:0!important}.site-brand-fallback{display:flex;align-items:center;gap:10px}.site-brand-fallback svg{width:42px;height:42px;flex:0 0 42px}.site-brand-fallback b{font-size:20px;color:#111}.rc-drawer-logo-img{display:block;width:44px;height:44px;object-fit:contain;border-radius:10px}
.site-logo-panel{margin:0 0 20px;padding:20px;border:1px solid #e2e8f0;border-radius:16px;background:linear-gradient(145deg,#fff,#f8fafc)}.site-logo-panel h3{margin:0 0 5px;font-size:19px}.site-logo-panel>p{margin:0 0 16px;color:#64748b}.site-logo-grid{display:grid;grid-template-columns:220px minmax(0,1fr);gap:20px;align-items:center}.site-logo-preview{display:grid;place-items:center;min-height:118px;padding:15px;border:1px dashed #cbd5e1;border-radius:14px;background:#fff}.site-logo-preview img{max-width:180px;max-height:82px;object-fit:contain}.site-logo-placeholder{display:grid;place-items:center;gap:8px;color:#94a3b8;text-align:center}.site-logo-placeholder svg{width:34px;height:34px;fill:none;stroke:currentColor;stroke-width:1.7}.site-logo-actions{display:flex;flex-wrap:wrap;gap:10px}.site-logo-upload,.site-logo-remove{display:inline-flex;align-items:center;gap:8px;padding:11px 15px;border-radius:11px;font-weight:700;cursor:pointer}.site-logo-upload{background:#111827;color:#fff}.site-logo-remove{border:1px solid #fecaca;background:#fff;color:#dc2626}.site-logo-upload svg,.site-logo-remove svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.8}.site-logo-help,.site-logo-status{display:block;margin-top:10px;font-size:12px;color:#64748b}.site-logo-status.ok{color:#15803d}.site-logo-status.bad{color:#dc2626}
@media(max-width:760px){.header .brand:has(.site-brand-logo),.header .brand:has(.site-brand-fallback){display:flex!important;align-items:center!important;min-width:52px!important}.site-brand-logo{max-width:145px!important;height:38px!important}.site-brand-fallback b{display:none}.site-brand-fallback svg{width:39px;height:39px}.site-logo-grid{grid-template-columns:1fr}.site-logo-preview{min-height:105px}}
`;document.head.append(style);
function fallback(name){return '<span class="site-brand-fallback"><svg viewBox="0 0 48 48" aria-hidden="true"><circle cx="24" cy="24" r="21" fill="#f26a21"/><circle cx="24" cy="24" r="8" fill="#fff"/></svg><b>'+esc(name||'Rentcam')+'</b></span>'}
function applyPublic(cfg=window.RENTCAM_CMS_CONFIG||{}){if(admin)return;const g=cfg.general||{},brand=document.querySelector('.header .brand');if(!brand)return;const logo=String(g.logoUrl||'').trim(),name=g.siteName||'Rentcam',sig=logo+'|'+name;const valid=logo?!!brand.querySelector('img[data-site-logo]'):!!brand.querySelector('.site-brand-fallback');if(brand.dataset.siteBrandSig!==sig||!valid){brand.dataset.siteBrandSig=sig;brand.innerHTML=logo?'<img class="site-brand-logo" data-site-logo src="'+esc(logo)+'" alt="'+esc(name)+'">':fallback(name)}const drawerLogo=document.querySelector('.rc-drawer-logo');if(drawerLogo){if(logo&&drawerLogo.dataset.logoSig!==logo){drawerLogo.dataset.logoSig=logo;drawerLogo.className='rc-drawer-logo rc-drawer-logo-img';drawerLogo.innerHTML='<img src="'+esc(logo)+'" alt="'+esc(name)+'" style="width:100%;height:100%;object-fit:contain">'}else if(!logo&&!drawerLogo.textContent.trim())drawerLogo.textContent='R'}}
if(!admin){let queued=false;const schedule=()=>{if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;applyPublic()})};document.addEventListener('rentcam-cms-updated',e=>applyPublic(e.detail));addEventListener('DOMContentLoaded',()=>{applyPublic();setTimeout(applyPublic,300);setTimeout(applyPublic,1000);new MutationObserver(schedule).observe(document.body,{childList:true,subtree:true})});applyPublic();return}
const icon='<svg viewBox="0 0 24 24"><path d="M4 5h16v14H4zM8 14l2.5-3 2 2 2.5-3 3 4"/></svg>';
function setStatus(panel,msg,type=''){const el=panel.querySelector('.site-logo-status');el.className='site-logo-status '+type;el.textContent=msg}
function refreshPreview(panel,url){panel.querySelector('.site-logo-preview').innerHTML=url?'<img src="'+esc(url)+'" alt="Preview logo website">':'<div class="site-logo-placeholder">'+icon+'<span>Belum ada logo website</span></div>'}
async function upload(file){if(!file||!/^image\/(png|jpeg|webp|svg\+xml)$/.test(file.type))throw Error('Pilih file PNG, JPG, WEBP.');if(file.size>5*1024*1024)throw Error('Ukuran logo maksimal 5 MB.');const r=await fetch(SB+'/rest/v1/rpc/rentcam_issue_upload_token',{method:'POST',headers:{apikey:KEY,'Content-Type':'application/json'},body:'{}'});if(!r.ok)throw Error('Tidak bisa membuat akses upload. Silakan login ulang.');const token=String(await r.json()).replace(/"/g,''),ext=({'image/png':'png','image/jpeg':'jpg','image/webp':'webp'})[file.type],path=[token,'website-logo',Date.now()+'-'+crypto.randomUUID()+'.'+ext].map(encodeURIComponent).join('/'),up=await fetch(SB+'/storage/v1/object/cms-media/'+path,{method:'POST',headers:{apikey:KEY,'Content-Type':file.type,'cache-control':'3600'},body:file});if(!up.ok)throw Error('Upload logo gagal.');return SB+'/storage/v1/object/public/cms-media/'+path}
function install(){const urlInput=document.querySelector('.v5-content [data-field="general.logoUrl"]');if(!urlInput)return;const card=urlInput.closest('.v5-card');if(!card||card.querySelector('.site-logo-panel'))return;const url=urlInput.value||window.RENTCAM_CMS_CONFIG?.general?.logoUrl||'';card.querySelector('.v5-head')?.insertAdjacentHTML('afterend','<section class="site-logo-panel"><h3>Logo Website</h3><p>Logo ini tampil di header website pada HP dan komputer.</p><div class="site-logo-grid"><div class="site-logo-preview"></div><div><div class="site-logo-actions"><label class="site-logo-upload"><svg viewBox="0 0 24 24"><path d="M12 16V4M7 9l5-5 5 5M5 20h14"/></svg>Upload logo<input type="file" data-site-logo-file accept="image/png,image/jpeg,image/webp" hidden></label><button type="button" class="site-logo-remove" data-site-logo-remove><svg viewBox="0 0 24 24"><path d="M4 7h16M9 7V4h6v3M7 7l1 13h8l1-13"/></svg>Hapus</button></div><small class="site-logo-help">PNG transparan disarankan. Maksimal 5 MB.</small><span class="site-logo-status">Setelah upload, klik tombol Simpan di kanan atas.</span></div></div></section>');const panel=card.querySelector('.site-logo-panel');refreshPreview(panel,url)}
document.addEventListener('change',async e=>{if(!e.target.matches('[data-site-logo-file]'))return;const panel=e.target.closest('.site-logo-panel'),file=e.target.files[0];setStatus(panel,'Mengupload logo...');try{const url=await upload(file),input=document.querySelector('[data-field="general.logoUrl"]');input.value=url;input.dispatchEvent(new Event('input',{bubbles:true}));refreshPreview(panel,url);setStatus(panel,'Logo berhasil diupload. Klik Simpan untuk menerapkan ke website.','ok')}catch(err){setStatus(panel,err.message,'bad')}finally{e.target.value=''}});
document.addEventListener('click',e=>{if(!e.target.closest('[data-site-logo-remove]'))return;const panel=e.target.closest('.site-logo-panel'),input=document.querySelector('[data-field="general.logoUrl"]');input.value='';input.dispatchEvent(new Event('input',{bubbles:true}));refreshPreview(panel,'');setStatus(panel,'Logo dihapus dari pengaturan. Klik Simpan.','ok')});
addEventListener('DOMContentLoaded',()=>{install();new MutationObserver(install).observe(document.body,{childList:true,subtree:true})});install()})();